export const money = n => new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2,minimumFractionDigits:Math.abs(n)%1 ? 2 : 0}).format(n);
export const sum = (rows,key) => Math.round(rows.reduce((v,r)=>v+r[key],0)*100)/100;
export function metrics(month){const scheduled=sum(month.units,'rent'),collected=sum(month.units,'paid');return {scheduled,collected,outstanding:sum(month.units.filter(u=>u.balance>0),'balance'),credits:-sum(month.units.filter(u=>u.balance<0),'balance'),rate:scheduled?collected/scheduled:null,settled:month.units.filter(u=>u.balance<=0).length};}
export function validate(data){if(!data||!Array.isArray(data.months)||!data.months.length||!data.months.every(m=>/^\d{4}-\d{2}$/.test(m.key)&&Array.isArray(m.units)&&m.units.every(u=>typeof u.unit==='string'&&['rent','paid','balance'].every(k=>Number.isFinite(u[k]))))||!Array.isArray(data.expenses)||!Array.isArray(data.budget)||!data.budget.every(b=>typeof b.label==='string'&&Number.isFinite(b.amount)))throw Error('The data feed has an unexpected format.');return data;}
